// ---- Lookup (hand-written) ----

/** `Google Sheets`, `google-sheets` and `google_sheets` all become `googlesheets`. */
const norm = (s: string) =>
  s
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]/g, '');

/** Catalogue ids and display names whose mark lives under another slug (normalised on both sides). */
const ALIASES: Record<string, string> = {
  calcom: 'caldotcom',
  convertkit: 'kit',
  klarnaandafterpay: 'klarna',
  whatsappbusiness: 'whatsapp',
  ga4: 'googleanalytics',
  googleanalytics4: 'googleanalytics',
  googleanalyticsreports: 'googleanalytics',
  googleadsapi: 'googleads',
  meet: 'googlemeet',
  googleworkspace: 'google',
  googlebusinessprofile: 'google',
  chromeuxreportapi: 'googlechrome',
  googlecrux: 'googlechrome',
  metaads: 'meta',
  metapixelandcapi: 'meta',
  metacloudapi: 'meta',
  metapages: 'facebook',
  facebookpageandinstagram: 'facebook',
  tiktokpixel: 'tiktok',
  tiktokads: 'tiktok',
  tiktokforbusiness: 'tiktok',
  pinterestads: 'pinterest',
  twitter: 'x',
  xads: 'x',
  microsoftads: 'microsoft',
  microsoftadvertising: 'microsoft',
  microsoftadvertisingapi: 'microsoft',
  intuitquickbooks: 'quickbooks',
  cloudflareforsaas: 'cloudflare',
  cloudflareregistrar: 'cloudflare',
  cloudflareturnstile: 'cloudflare',
  turnstile: 'cloudflare',
  cloudflarer2: 'cloudflare',
  r2: 'cloudflare',
  expopush: 'expo',
  prometheusmetrics: 'prometheus',
  teams: 'microsoftteams',
  outlook: 'microsoftoutlook',
  outlookcalendar: 'microsoftoutlook',
  linkedininsight: 'linkedin',
  linkedinads: 'linkedin',
  linkedinpage: 'linkedin',
  linkedinpages: 'linkedin',
  watershedlrs: 'watershed',
  keyos: 'buydrm',
  buydrmkeyos: 'buydrm',
  s3: 'amazons3',
  awss3: 'amazons3',
  ses: 'amazonses',
  dailyco: 'daily',
  // SendGrid and Segment are Twilio products: their sites now carry the Twilio mark.
  sendgrid: 'twilio',
  twiliosendgrid: 'twilio',
  segment: 'twilio',
  twiliosegment: 'twilio',
};

/** The mark for a catalogue id, connection key or display name; undefined when there is none (use `monogram`). */
export function markOf(brand: string): Mark | undefined {
  const k = norm(brand);
  return MARKS[ALIASES[k] ?? k];
}

/** The fallback tile text: the first letters of two words, or of a camel-cased name ("ActiveCampaign" → "AC"). */
export function monogram(name: string): string {
  const words = name.split(/[^A-Za-z0-9]+/).filter(Boolean);
  const first = words[0] ?? '';
  const second = words.length > 1 ? (words[1]?.[0] ?? '') : (/[A-Z]/.exec(first.slice(1))?.[0] ?? '');
  return (first.charAt(0) + second).toUpperCase();
}

/** Whether `brand` has a real mark (callers that would rather show nothing than a monogram, e.g. inside a pill). */
export const hasBrandLogo = (brand: string) => markOf(brand) !== undefined;
